package io.github.polestarcn.companion;
import static org.junit.Assert.*;import android.content.*;import android.graphics.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class EffectsBeta9Test {
 private Context c;private RectF b=new RectF(100,80,500,280);
 @Before public void start(){c=RuntimeEnvironment.getApplication();c.getSharedPreferences("preferences",0).edit().clear().commit();}
 @Test public void cLayoutRemainsOptInAndOrangeWeightIsConfigurable(){assertEquals("below",AppPreferences.get(c,"all_good_position","below"));assertEquals("one",AppPreferences.get(c,"all_good_lines","one"));AllGoodTextView v=new AllGoodTextView(c);AppPreferences.set(c,"all_good_weight","300");v.setText("All Good！");assertEquals(300,v.getTypeface().getWeight());AppPreferences.set(c,"all_good_weight","900");v.setText("All Good！");assertEquals(900,v.getTypeface().getWeight());}
 @Test public void everyDirectionEndsAtCenterAndRespectsRangeAndZeroDensity(){AppPreferences.set(c,"fx_air_direction","absorb");AppPreferences.set(c,"fx_turbulence","off");AirflowRenderer renderer=new AirflowRenderer();String[] keys={"fx_density_top","fx_density_bottom","fx_density_left","fx_density_right"};float[] point=new float[2];for(int side=0;side<4;side++){for(int j=0;j<4;j++)AppPreferences.set(c,keys[j],j==side?"100":"0");EffectSettings p=new EffectSettings(c);assertEquals(side,AirflowRenderer.side(.5f,p));renderer.position(b,true,0,1,p,point);assertEquals(b.centerX(),point[0],.001);assertEquals(b.centerY(),point[1],.001);renderer.position(b,true,0,0,p,point);float d1=(float)Math.hypot(point[0]-b.centerX(),point[1]-b.centerY());AppPreferences.set(c,"fx_absorb_range","200");renderer.position(b,true,0,0,new EffectSettings(c),point);assertEquals(d1*2,Math.hypot(point[0]-b.centerX(),point[1]-b.centerY()),.001);AppPreferences.set(c,"fx_absorb_range","100");}
 for(String key:keys)AppPreferences.set(c,key,"0");Bitmap image=Bitmap.createBitmap(700,400,Bitmap.Config.ARGB_8888);renderer.draw(new Canvas(image),b,true,2,1,new EffectSettings(c),EffectStateController.Mode.HEATING,120,1);assertEquals(0,pixels(image));}
 @Test public void curvedTrailSamplesAreNotCollinearAndBothLayersRender(){AppPreferences.set(c,"fx_turbulence_percent","100");AppPreferences.set(c,"fx_arc_percent","70");AppPreferences.set(c,"fx_air_direction","absorb");AirflowRenderer renderer=new AirflowRenderer();EffectSettings p=new EffectSettings(c);float[] a=new float[2],h=new float[2],z=new float[2];renderer.position(b,true,4,.25f,p,a);renderer.position(b,true,4,.35f,p,h);renderer.position(b,true,4,.45f,p,z);assertTrue(Math.abs((h[0]-a[0])*(z[1]-a[1])-(h[1]-a[1])*(z[0]-a[0]))>.1);
 for(String shape:new String[]{"streaks","spheres"})for(EffectStateController.Mode mode:new EffectStateController.Mode[]{EffectStateController.Mode.COOLING,EffectStateController.Mode.HEATING,EffectStateController.Mode.PURIFICATION}){AppPreferences.set(c,"fx_air_shape",shape);p=new EffectSettings(c);for(int layer=0;layer<2;layer++){Bitmap image=Bitmap.createBitmap(700,400,Bitmap.Config.ARGB_8888);renderer.drawLayer(new Canvas(image),b,true,1.7f,1,p,mode,120,1,layer);assertTrue(pixels(image)>20);image.recycle();}}EffectSettings.defaults(c);assertFalse(new EffectSettings(c).airSpheres);assertEquals(100,new EffectSettings(c).topDensity);}
 private int pixels(Bitmap b){int n=0;for(int y=0;y<b.getHeight();y++)for(int x=0;x<b.getWidth();x++)if(Color.alpha(b.getPixel(x,y))>0)n++;return n;}
}
